INSERT INTO default.map_hr_kpi (kpi_code, kind, kpi_name, short_label, area, definition, formula, source_system, grain, caveats, direction, value_format, display_order, measure_name, bsc_kpi_code, target_source, needs_pay, is_home_tile, status, changed_at, changed_by, change_note, is_deleted) VALUES
    ('HR_HEADCOUNT', 'kpi', 'Headcount', 'Headcount', 'Size', 'Month-end headcount of the last closed month in the selection, contingent workers excluded.', 'Employees on the payroll at month end, without contingent workers.', 'Fusion', 'Employee, month', 'Snapshot: never summed over months. The current, unfinished month is excluded.', 'on_target', 'num', 1, 'Headcount', '', 'fixed', 0, 1, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_CONTINGENT_SHARE', 'kpi', 'Contingent Share %', 'Contingent Share', 'Size', 'Contingent workers as a share of all heads at the last closed month in the selection.', 'Contingent heads divided by all heads.', 'Fusion', 'Employee, month', 'Snapshot. New measure.', 'lower', 'pct', 2, 'Contingent Share %', '', 'fixed', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_SAUDIZATION', 'kpi', 'Saudization', 'Saudization', 'Mix', 'Saudi heads divided by heads without part-time doctors, at the last closed month of the period, added over hospitals.', 'Saudi heads divided by headcount without part-time doctors.', 'Fusion', 'Employee, month', 'Snapshot. Same figure as the balanced scorecard (KPI 46).', 'higher', 'pct', 3, 'BSC Saudization', 'LRN_SAUDIZATION', 'fixed', 0, 1, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_FEMALE_SHARE', 'kpi', 'Female Share %', 'Female Share', 'Mix', 'Female employees as a share of headcount at the last closed month in the selection.', 'Female heads divided by headcount.', 'Fusion', 'Employee, month', 'Snapshot. New measure. Employees with no gender recorded are listed on the Data quality page.', 'on_target', 'pct', 4, 'Female Share %', '', 'fixed', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_TURNOVER', 'kpi', 'Turnover %', 'Turnover', 'Flow', 'Resignations (Oasis for hospitals 1 to 5, Fusion voluntary leavers for hospitals 6 to 8) divided by average headcount, scorecard rules.', 'Resignations divided by average headcount.', 'Oasis and Fusion', 'Hospital, month', 'The headline turnover everywhere. Same figure as the balanced scorecard (KPI 43). The annual target is pro-rated by the months selected.', 'lower', 'pct', 5, 'BSC Turnover', 'LRN_TURNOVER', 'fixed', 0, 1, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_NEW_HIRE_TURNOVER', 'kpi', 'New Hire Turnover %', 'New Hire Turnover', 'Flow', 'Leavers within 12 months of their hire date as a share of the hires of the prior 12 months.', 'Leavers within 12 months of hire divided by hires in the prior 12 months.', 'Fusion', 'Employee, month', 'New measure. Counts Fusion leavers, so it does not reconcile with Turnover %.', 'lower', 'pct', 6, 'New Hire Turnover %', '', 'fixed', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_STAFF_COST_PER_FTE', 'kpi', 'Staff Cost per FTE', 'Staff Cost per FTE', 'Cost', 'Payroll cost in SAR divided by the average FTE of the period.', 'Payroll cost divided by average FTE.', 'Fusion payroll', 'Hospital, month', 'Needs pay access: shown as Requires pay access for other users. Same measure as Payroll Cost per FTE.', 'lower', 'sar', 7, 'Payroll Cost per FTE', '', 'fixed', 1, 1, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_REVENUE_PER_FTE', 'kpi', 'Revenue per FTE', 'Revenue per FTE', 'Productivity', 'GL net revenue divided by average FTE, part-time doctors at 0.5.', 'Net revenue divided by average FTE.', 'Oasis and Fusion GL, Fusion', 'Hospital, month', 'Same figure and target as the balanced scorecard (KPI 44), so the HR status equals the BSC status.', 'higher', 'sar', 8, 'BSC Revenue per FTE', 'LRN_REVENUE_PER_FTE', 'bsc', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_OVERTIME_SHARE', 'kpi', 'Overtime Share %', 'Overtime Share', 'Cost', 'Overtime gross pay divided by gross pay.', 'Overtime gross pay divided by gross pay.', 'Fusion payroll', 'Hospital, month', 'Needs pay access. Flow: covers the selection.', 'lower', 'pct', 9, 'Overtime Share %', '', 'fixed', 1, 1, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_SICK_LEAVE_RATE', 'kpi', 'Sick Leave Rate %', 'Sick Leave Rate', 'Absence', 'Sick days divided by month-end FTE times past calendar days, over months with a closed headcount.', 'Sick days divided by (month-end FTE times past calendar days).', 'Fusion', 'Hospital, month', 'Flow: covers the selection. Planned absence in the future is not counted.', 'lower', 'pct', 10, 'Sick Leave Rate %', '', 'fixed', 0, 1, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_LEAVE_LIABILITY', 'kpi', 'Leave Liability', 'Leave Liability', 'Leave', 'Annual leave balance valued in SAR at the last closed accrual month of the selection per hospital.', 'Leave balance in days times the daily salary rate.', 'Fusion', 'Employee, plan, month', 'Needs pay access. Snapshot. Balances with no salary carry no liability.', 'lower', 'sar', 11, 'Leave Liability', '', 'fixed', 1, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_VACANCY_RATE', 'kpi', 'Vacancy Rate %', 'Vacancy Rate', 'Hiring', 'Requisition openings still open at the end of the period divided by the budgeted FTE of that year.', 'Open requisition openings divided by budgeted FTE.', 'Fusion recruiting, BI budgeted FTE', 'Hospital, month', 'Snapshot. Same figure as the balanced scorecard (KPI 47).', 'lower', 'pct', 12, 'BSC Vacancy Rate', 'LRN_VACANCY_RATE', 'fixed', 0, 1, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_TIME_TO_FILL', 'kpi', 'Time to Fill (days)', 'Time to Fill', 'Hiring', 'Average days from requisition approval to fill, for the requisitions filled in the period.', 'Average of (filled date minus approved date) over requisitions filled in the period.', 'Fusion recruiting', 'Requisition', 'Same figure as the balanced scorecard (KPI 48).', 'lower', 'days', 13, 'BSC Time to Fill (days)', 'LRN_TIME_TO_FILL', 'fixed', 0, 1, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_STAFF_TO_BED', 'kpi', 'Staff to Bed', 'Staff to Bed', 'Productivity', 'Average FTE of doctors and clinical staff divided by average available inpatient beds.', 'Average clinical FTE divided by average available beds.', 'Fusion, BSC licensed beds', 'Hospital, month', 'Same figure as the balanced scorecard (KPI 45).', 'on_target', 'num', 14, 'BSC Staff to Bed', 'LRN_STAFF_TO_BED', 'fixed', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_CLINICAL_TO_DOCTOR', 'kpi', 'Clinical to Doctor', 'Clinical to Doctor', 'Productivity', 'Average clinical staff (nursing, paramedical and physical therapy) divided by average doctors, part-time doctors included.', 'Average clinical staff divided by average doctors.', 'Fusion', 'Hospital, month', 'Same figure as the balanced scorecard (KPI 68).', 'higher', 'num', 15, 'BSC Clinical to Doctor', 'LRN_CLINICAL_TO_DOCTOR', 'fixed', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_REVENUE_PER_DOCTOR', 'kpi', 'Revenue per Doctor', 'Revenue per Doctor', 'Productivity', 'GL net revenue divided by average doctors, part-time doctors included.', 'Net revenue divided by average doctors.', 'Oasis and Fusion GL, Fusion', 'Hospital, month', 'Same figure as the balanced scorecard (KPI 55).', 'higher', 'sar', 16, 'BSC Revenue per Doctor', 'FIN_REVENUE_PER_DOCTOR', 'fixed', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_VISITS_PER_FTE', 'kpi', 'Visits per FTE', 'Visits per FTE', 'Productivity', 'Encounters seen divided by FTE-months of linked doctors and nurses.', 'Encounters seen divided by FTE-months of linked doctors and nurses.', 'Oasis and Fusion', 'Hospital, month', 'Needs pay access. Only doctors and nurses linked between Oasis and Fusion count.', 'higher', 'num', 17, 'Visits per FTE', '', 'fixed', 1, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_REVENUE_PER_PAYROLL_SAR', 'kpi', 'Revenue per Payroll SAR', 'Revenue per Payroll SAR', 'Productivity', 'Revenue divided by the payroll cost of linked doctors and nurses, a ratio of sums.', 'Revenue divided by payroll cost of linked doctors and nurses.', 'Oasis and Fusion', 'Hospital, month', 'Needs pay access. Only doctors and nurses linked between Oasis and Fusion count.', 'higher', 'num', 18, 'Revenue per Payroll SAR', '', 'fixed', 1, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_M_FTE', 'metric', 'FTE', 'FTE', 'Size', 'Month-end FTE of the last closed month in the selection per hospital, contingent workers excluded.', 'Sum of FTE of employees on the payroll at month end.', 'Fusion', 'Employee, month', 'Snapshot. An FTE of 0 in Fusion is replaced by 1 (see the Data quality page).', 'on_target', 'num', 19, 'FTE', '', 'none', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_M_AVERAGE_HEADCOUNT', 'metric', 'Average Headcount', 'Average Headcount', 'Size', 'Average month-end headcount over the closed months of the selection, from 2026.', 'Sum of month-end headcounts divided by the closed months.', 'Fusion', 'Month', '', 'on_target', 'num', 20, 'Average Headcount', '', 'none', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_M_AVERAGE_FTE', 'metric', 'Average FTE', 'Average FTE', 'Size', 'Average month-end FTE over the closed months of the selection.', 'Sum of month-end FTE divided by the closed months.', 'Fusion', 'Month', '', 'on_target', 'num', 21, 'Average FTE', '', 'none', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_M_HIRES', 'metric', 'Hires', 'Hires', 'Flow', 'Hire movements in the period.', 'Count of hire movements.', 'Fusion', 'Movement', 'Counts Fusion movements, so rehires are included.', 'on_target', 'num', 22, 'Hires', '', 'none', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_M_LEAVERS', 'metric', 'Leavers', 'Leavers in Fusion', 'Flow', 'Leaver movements in the period, as recorded in Fusion.', 'Count of leaver movements.', 'Fusion', 'Movement', 'Always labelled in Fusion. Not scored: it does not reconcile with Turnover %.', 'lower', 'num', 23, 'Leavers', '', 'none', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_M_VOLUNTARY_TURNOVER_RATE', 'metric', 'Voluntary Turnover Rate %', 'Voluntary leaver rate in Fusion', 'Flow', 'Voluntary leavers divided by average month-end headcount of the period, from 2026.', 'Voluntary leavers divided by average headcount.', 'Fusion', 'Month', 'Always labelled in Fusion. Does not reconcile with Turnover %, which uses Oasis resignations for hospitals 1 to 5. Not scored.', 'lower', 'pct', 24, 'Voluntary Turnover Rate %', '', 'none', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_M_PAYROLL_COST', 'metric', 'Payroll Cost', 'Payroll Cost', 'Cost', 'Payroll cost in SAR: the sum of cost amounts, parallel-run rows already excluded.', 'Sum of payroll cost amounts.', 'Fusion payroll', 'Hospital, month', 'Needs pay access.', 'lower', 'sar', 25, 'Payroll Cost', '', 'none', 1, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_M_GROSS_PAY', 'metric', 'Gross Pay', 'Gross Pay', 'Cost', 'Gross pay in SAR, parallel-run rows already excluded, open Oasis payroll included.', 'Sum of gross pay.', 'Fusion payroll', 'Hospital, month', 'Needs pay access. Includes payroll that is not closed yet, so it can change.', 'lower', 'sar', 26, 'Gross Pay', '', 'none', 1, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_M_GROSS_PAY_OPEN', 'metric', 'Gross Pay (Open Payroll)', 'Gross Pay (Open Payroll)', 'Cost', 'Gross pay in SAR of payroll the hospital has not closed yet.', 'Sum of gross pay of open payroll.', 'Fusion payroll', 'Hospital, month', 'Needs pay access. Changes until the month is closed.', 'lower', 'sar', 27, 'Gross Pay (Open Payroll)', '', 'none', 1, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_M_SICK_DAYS', 'metric', 'Sick Days', 'Sick Days', 'Absence', 'Counted sick-leave days up to today.', 'Sum of sick-leave days up to today.', 'Fusion', 'Absence, day', 'Planned absence in the future is not counted.', 'lower', 'days', 28, 'Sick Days', '', 'none', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_M_LEAVE_BALANCE', 'metric', 'Leave Balance (days)', 'Leave Balance (days)', 'Leave', 'Leave balance in days at the last closed accrual month of the selection per hospital: the latest period of each employee and plan.', 'Sum of the latest leave balance of each employee and plan.', 'Fusion', 'Employee, plan, month', 'Snapshot.', 'lower', 'days', 29, 'Leave Balance (days)', '', 'none', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_M_CURRENT_LEAVE_BALANCE', 'metric', 'Current Leave Balance (days)', 'Current Leave Balance (days)', 'Leave', 'Leave balance in days at the latest closed accrual period, whatever dates are selected.', 'Sum of the latest leave balance of each employee and plan.', 'Fusion', 'Employee, plan', 'Latest-position measure: ignores the dates selected.', 'lower', 'days', 30, 'Current Leave Balance (days)', '', 'none', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_M_CURRENT_LEAVE_LIABILITY', 'metric', 'Current Leave Liability', 'Current Leave Liability', 'Leave', 'Leave liability in SAR at the latest closed accrual period, whatever dates are selected.', 'Leave balance in days times the daily salary rate, at the latest period.', 'Fusion', 'Employee, plan', 'Needs pay access. Latest-position measure: ignores the dates selected.', 'lower', 'sar', 31, 'Current Leave Liability', '', 'none', 1, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_M_AVERAGE_LEAVE_BALANCE', 'metric', 'Average Leave Balance (days)', 'Average Leave Balance (days)', 'Leave', 'Leave balance in days per employee at the last closed accrual month of the selection.', 'Leave balance in days divided by employees holding a balance.', 'Fusion', 'Employee, month', 'New measure. Snapshot.', 'lower', 'days', 32, 'Average Leave Balance (days)', '', 'none', 0, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('HR_M_PAYROLL_COST_PER_VISIT', 'metric', 'Payroll Cost per Visit', 'Payroll Cost per Visit', 'Productivity', 'Payroll cost in SAR divided by encounters seen of linked doctors and nurses.', 'Payroll cost divided by encounters seen of linked doctors and nurses.', 'Oasis and Fusion', 'Hospital, month', 'Needs pay access.', 'lower', 'sar', 33, 'Payroll Cost per Visit', '', 'none', 1, 0, 'active', now64(3), 'seed', 'seed 2026-11-02', 0);
INSERT INTO default.map_hr_dq_issue (issue_code, issue_name, area, fix_in, owner, severity, how_to_fix, display_order, status, changed_at, changed_by, change_note, is_deleted) VALUES
    ('DQ_EMP_NO_STAFF', 'Fusion employee with no Oasis staff record', 'Linkage', 'Oasis or Fusion', 'HR', 'Medium', 'Fusion employee whose worker number has no Oasis staff record at the same hospital. Create the staff record in Oasis, or correct the worker number in Fusion.', 1, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_STAFF_NO_EMP', 'Active Oasis staff with no Fusion employee', 'Linkage', 'Fusion', 'HR', 'Medium', 'Active Oasis staff member with no Fusion employee at the same hospital. Create the employee in Fusion, or deactivate the Oasis staff record.', 2, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_STAFF_MANY_EMP', 'One Oasis staff record linked to several Fusion employees', 'Linkage', 'Oasis', 'HR', 'Medium', 'One Oasis staff record matches several Fusion employees. Correct the staff ID or worker number in Oasis so each employee has one staff record.', 3, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_STAFF_ID_FORMAT', 'Oasis staff IDs that differ only in format', 'Linkage', 'Oasis', 'HR', 'Medium', 'Oasis staff IDs that are the same apart from format (case, spaces, leading zeros). Merge them into one staff ID in Oasis.', 4, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_EMP_DUP_WORKER_NO', 'Duplicate worker numbers or duplicate people in Fusion', 'Employee', 'Fusion', 'HR', 'Medium', 'The same worker number is used by more than one person, or one person has several records. Correct the worker number or merge the person records in Fusion.', 5, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_FTE_ZERO', 'FTE of 0 replaced by 1', 'Employee', 'Fusion', 'HR', 'Medium', 'Fusion holds an FTE of 0 for an active assignment and the model uses 1. Enter the real FTE on the assignment in Fusion.', 6, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_LEAVE_DUP_PERIOD', 'Duplicate leave balance entries in a period', 'Leave', 'Fusion', 'HR', 'Medium', 'More than one leave balance entry for the same employee, plan and period. Remove the duplicate entry in Fusion.', 7, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_ABSENCE_OVERLAP', 'Overlapping absences', 'Absence', 'Fusion', 'HR', 'Medium', 'Two absences of the same employee cover the same days. Correct the dates or cancel one absence in Fusion.', 8, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_ABSENCE_ZERO_DAYS', 'Absences with zero days', 'Absence', 'Fusion', 'HR', 'Medium', 'An absence is recorded with zero days. Correct the dates or cancel the absence in Fusion.', 9, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_LEAVE_NO_SALARY', 'Annual leave balance with no salary', 'Leave', 'Fusion', 'HR', 'Medium', 'An employee holds an annual leave balance but has no salary, so the leave liability is zero. Enter the salary in Fusion.', 10, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_PAY_CODE_UNMAPPED', 'Pay codes not mapped to a pay category', 'Payroll', 'BI', 'BI', 'Medium', 'A payroll element code has no row in map_pay_category, so its amount is not in a pay category. The BI team adds the mapping.', 11, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_B8_PAYROLL_COPY', 'Branch 8 payroll copies Branch 7', 'Payroll', 'Fusion payroll', 'HR', 'Medium', 'Branch 8 payroll for January to April 2026 repeats Branch 7. Reload the Branch 8 payroll from Fusion payroll.', 12, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_PAYROLL_MONTH_MISSING', 'Hospital-months with no payroll', 'Payroll', 'Fusion payroll', 'HR', 'Medium', 'A hospital has no payroll for a month in which it has employees. Load the missing payroll month from Fusion payroll.', 13, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_LEAVE_BALANCE_STOPS', 'Leave balances that stop', 'Leave', 'Fusion', 'HR', 'Medium', 'A hospital\'s leave balances stop before the latest month. Run the leave accrual for the missing months in Fusion.', 14, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_TERMINATED_WITH_BALANCE', 'Terminated employees still holding a current leave balance', 'Leave', 'Fusion', 'HR', 'Medium', 'A terminated employee still has a current leave balance. Settle or clear the balance in Fusion.', 15, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_FUTURE_DATED', 'Movements or absences dated more than a year ahead', 'Employee', 'Fusion', 'HR', 'Medium', 'A movement or an absence is dated more than 12 months after today, most likely a wrong year. Correct the date in Fusion, or confirm it is planned.', 16, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_NO_HOSPITAL', 'Contractors with no hospital', 'Employee', 'Fusion', 'HR', 'Medium', 'A contractor has no hospital (branch 0) and is counted under Head Office. Assign the hospital in Fusion.', 17, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_LEGAL_EMPLOYER_MISMATCH', 'Legal employer of the latest period of service differs from the assignment', 'Employee', 'Fusion', 'HR', 'Medium', 'The legal employer of the latest period of service differs from the legal employer of the assignment. Correct the legal employer in Fusion.', 18, 'active', now64(3), 'seed', 'seed 2026-11-02', 0),
    ('DQ_MISSING_ATTRIBUTE', 'Active employees missing gender, nationality, birth date, department, job or grade', 'Employee', 'Fusion', 'HR', 'Medium', 'An active employee has no gender, nationality, birth date, department, job or grade. Complete the person record in Fusion.', 19, 'active', now64(3), 'seed', 'seed 2026-11-02', 0);
